let N_MAX= 4e6

let sh;
let img;
let verts;
function preload(){
	img= loadImage('https://openprocessing.org/sketch/1593240/files/goghgy.jpg')//todo async

	sh = loadShader('https://openprocessing.org/sketch/1593240/files/vert.glsl', 'frag.glsl');

	verts = new Float32Array(N_MAX*3).map((e,i)=>random()*2-1);
}

var gl
p5.RendererGL.prototype._initContext = function() {// hack thx to github.com/diwi/p5.EasyCam/blob/master/examples/ReactionDiffusion_Webgl2/ReactionDiffusion_Webgl2.js#L563
  this.drawingContext = this.canvas.getContext('webgl2',this._pInst._glAttributes);
	if (this.drawingContext===null)
		alert('couldnt webgl2');
	gl= this.drawingContext;
};


let canv, W,H, ping,pong, xfb, tex,u_tex
function setup() {
	W = windowWidth;
	H = windowHeight;
  canv= createCanvas(W,H, WEBGL);;
  pixelDensity(1);

	function buf(){
		let vbo = gl.createBuffer();;
		gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
		gl.bufferData(gl.ARRAY_BUFFER, verts, gl.DYNAMIC_DRAW);

		let vao= gl.createVertexArray();
		gl.bindVertexArray(vao);
		gl.enableVertexAttribArray(0);;
		gl.vertexAttribPointer(0,3,gl.FLOAT,false,0,0);;

  	let xfb = gl.createTransformFeedback();
		gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, xfb);
		gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 0, vbo);;

		gl.bindVertexArray(null);
		gl.bindBuffer(gl.ARRAY_BUFFER, null);
		gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, null);;

		this.vbo= vbo;
		this.vao= vao;
		this.xfb= xfb;
	}
	ping= new buf();
	pong= new buf();


	//inject before the link stage
	//javascript.jpeg angels cry yet god laughs``````````````````````````````````````````````````````````````````````````````````````
	let hax= gl.linkProgram;
	Object.defineProperty( gl,'linkProgram', {get:(function() { 
		gl.transformFeedbackVaryings((()=>sh._glProgram)(), ['v_pos'], gl.INTERLEAVED_ATTRIBS);
		gl.linkProgram= hax; //run once
		return hax;
	})});
	shader(sh);

	//force shader compilation or something like that
	//this is necessary, even without the xform varyings, required before the draw loop
  rect(0,0,0,0);;


	tex= texture(img) 
							 /*,settings={
  	//glFormat:gl.SRGBA,
  	glMinFilter: gl.NEAREST,
  	glMagFilter: gl.NEAREST,
  	glWrapS: gl.CLAMP_TO_EDGE,
  	glWrapT: gl.CLAMP_TO_EDGE,
							 })*/
	u_tex= gl.getUniformLocation(sh._glProgram,"tex")

	let err= gl.getError();
	if(err)
		print(err);;
}
pingpong=()=>{[ping,pong]=[pong,ping];}


function draw() {
	n= lod(deltaTime/1000)*N_MAX;

	gl.clearColor(0,0,0,1);//canvas has alpha. fbo0 is externally blended
	gl.clear(gl.COLOR_BUFFER_BIT);;

	//gl.enable(gl.GL_FRAMEBUFFER_SRGB)
	gl.disable(gl.DEPTH_TEST);
	gl.disable(gl.CULL_FACE);
	gl.enable(gl.BLEND);
	gl.blendFunc(gl.SRC_ALPHA,gl.ONE);
	//gl.enable(gl.PROGRAM_POINT_SIZE) always on in webgl

  shader(sh);
	sh.setUniform('time', millis());//texture bind
	sh.setUniform('u_tex', img);//texture bind
	gl.bindTexture(gl.TEXTURE2D,tex.glTex);


	gl.bindVertexArray(ping.vao);
	gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, pong.xfb);
	gl.beginTransformFeedback(gl.POINTS);
	gl.drawArrays(gl.POINTS,0,n);
	gl.endTransformFeedback();
	gl.bindVertexArray(null);

	pingpong();

	//print(gl.getError())
}
